<?php ob_start(); ?><h1><?= $signature?e(t('Edit')):e(t('Create')) ?> <?= e(t('signature')) ?></h1><?php if(($signature['pattern_type']??'')==='hash'): ?><p class="muted"><?= e(t('Pre-filled as an exact-hash signature from the source finding: matches only byte-identical copies of this file anywhere on the server, on the next scan. Switch pattern_type to "combo" and edit pattern_json below to also catch renamed/modified variants using distinctive code snippets from the preview.')) ?></p><?php endif ?><form method="post" action="/signatures/save"><input type="hidden" name="id" value="<?= e($signature['id']??'') ?>"><p><input class="input" name="name" placeholder="<?= e(t('name')) ?>" value="<?= e($signature['name']??'') ?>"> <input class="input" name="slug" placeholder="slug" value="<?= e($signature['slug']??'') ?>"></p><p><input class="input" name="risk" value="<?= e($signature['risk']??'medium') ?>"> <input class="input" name="type" value="<?= e($signature['type']??'suspicious_php') ?>"> <input class="input" name="pattern_type" value="<?= e($signature['pattern_type']??'combo') ?>"></p><p><textarea class="input" name="description" rows="3" cols="100"><?= e($signature['description']??'') ?></textarea></p><p><textarea class="input" name="pattern_json" rows="12" cols="100"><?= e($signature['pattern_json']??'{}') ?></textarea></p><button class="btn"><?= e(t('Save as manual signature')) ?></button></form><?php if(!empty($preview)): ?><div class="card"><h2><?= e(t('Source file preview')) ?></h2><p class="muted"><?= e(t('Read-only. Copy distinctive substrings from here into a combo pattern (any/regex_any/all) for fuzzy matching.')) ?></p><pre><?= e($preview) ?></pre></div><?php endif ?><?php $content=ob_get_clean(); include base_path('resources/views/layouts/app.php'); ?>